public without sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Asynchronously recalculates the Rating on all supplied Accounts
     * based on their open pipeline.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Bulk fetch all open opportunities for the affected accounts
        List<Opportunity> openOpps = [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
        ];

        // Group by account
        Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity opp : openOpps) {
            if (!oppsByAccount.containsKey(opp.AccountId)) {
                oppsByAccount.put(opp.AccountId, new List<Opportunity>());
            }
            oppsByAccount.get(opp.AccountId).add(opp);
        }

        // Determine the new rating for each account
        Map<Id, String> newRatings = new Map<Id, String>();
        for (Id accountId : accountIds) {
            List<Opportunity> opps = oppsByAccount.get(accountId);
            if (opps == null || opps.isEmpty()) {
                newRatings.put(accountId, 'Cold');
            } else {
                String rating = 'Warm';
                for (Opportunity opp : opps) {
                    if (opp.Amount != null && opp.Amount >= HOT_THRESHOLD) {
                        rating = 'Hot';
                        break;
                    }
                }
                newRatings.put(accountId, rating);
            }
        }

        // Fetch accounts and update only those whose rating changed
        List<Account> accounts = [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ];

        List<Account> toUpdate = new List<Account>();
        for (Account acc : accounts) {
            String newRating = newRatings.get(acc.Id);
            if (newRating != null && acc.Rating != newRating) {
                acc.Rating = newRating;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
