public class CaseSurveyJob implements Queueable {

    private final Id caseId;
    private final List<Id> batchIds;

    /**
     * Single-case constructor – processes one Case.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.batchIds = null;
    }

    /**
     * Dispatcher constructor – fans out individual jobs in chunks to stay
     * within the 50-enqueue-per-transaction governor limit.
     */
    public CaseSurveyJob(List<Id> batchIds) {
        this.caseId = null;
        this.batchIds = batchIds;
    }

    public void execute(QueueableContext context) {
        if (batchIds != null) {
            dispatch();
        } else {
            processCase();
        }
    }

    /**
     * Enqueues up to 49 individual CaseSurveyJob instances, then enqueues
     * one more dispatcher for any remaining IDs. This keeps each transaction
     * within the 50-enqueue limit while the async stack depth stays well
     * under 50 (for 200 cases the depth is only ~6).
     */
    private void dispatch() {
        Integer batchSize = Math.min(49, batchIds.size());

        for (Integer i = 0; i < batchSize; i++) {
            System.enqueueJob(new CaseSurveyJob(batchIds.get(i)));
        }

        batchIds.remove(0, batchSize);

        if (!batchIds.isEmpty()) {
            System.enqueueJob(new CaseSurveyJob(batchIds));
        }
    }

    private void processCase() {
        Case c = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :caseId];

        // Defensive: the case may have been deleted or its contact cleared
        // between enqueue and execution
        if (c == null || c.ContactId == null) {
            return;
        }

        Task t = new Task(
            WhatId       = c.Id,
            WhoId        = c.ContactId,
            Subject      = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status       = 'Not Started'
        );

        insert t;
    }
}
